  const rim = new Mesh(new CylinderGeometry(ro, ro, THICK, 96, 1, true), new MeshStandardMaterial({ color: 0x140A24, metalness: 0.5, roughness: 0.3,
    emissive: 0xFF3FD0, emissiveIntensity: 0.3 }));
