  animateRings(now, dt);
  animatePieces(dt);
  animateCrossings();
  animateRides();
  animateTints(dt);
  animateWormholes(dt);
  animateRipple(dt);
  animateMagsAndWinds(dt);
  animateRounds(dt);
  animateTubes();
  animateSwitches(dt);
  animateScans();
  animateFlames();
  animateCracks(dt);
  animateBlocks();
  animatePlazas(dt);
  animateSpace(dt); animateSpace2(dt); animateCirc(dt);
