  L.push([new BoxGeometry(0.44, 0.34, 0.06), SUMI, placeAt(0, high + 0.35, 0.1)]);                        // and the tablet on it
  L.push([new BoxGeometry(span + 1.5, 0.16, 0.3), VERMILION, placeAt(0, high + 0.58, 0)]);
