  fog: [0x160C06, 55, 280], hemi: [0xFFD8A0, 0x2A1208, 0.8], sun: [0xFFE2B8, 1.7], haze: [0xFFB860, 3],
  gi: 0xFFD49A, ins: [0xFF3A2A, 0xFFB43A, 0x3ADC6A, 0x4A9AFF, 0xFFF0D0, 0xFF6A2A],
