      for (let k = 0; k <= 24; k++) { const a = Math.PI * 6 - k / 24 * Math.PI * 4; dn.push([cx + Math.cos(a) * 1.9, top + 0.5 - (top + 0.5 - BY) * k / 24, cz + Math.sin(a) * 1.9]); }
