      for (const dx of [-4.5, 4.5]) metal.geo(new CylinderGeometry(0.25, 0.3, y - PF - 1.6, 8), placeAt(x + dx, PF + (y - PF - 1.6) / 2, z + 1), 0xC8D0D8);
