      for (let k = 0; k < 24; k++) { const a = k / 24 * Math.PI * 2; g.fillStyle = k % 2 ? '#FFF6DC' : '#FFD890'; pbCircle(g, 256 + Math.cos(a) * 246, 256 + Math.sin(a) * 246, 8); g.fill(); }
