      for (let k = 0; k < 3; k++) lamp('star', Sc.x - s * (2.8 + k * 2.4), Sc.z - 1 - k * 1.1, 1.8, 1.8, 0, L.ins[k % 3], () => (Sc.held ? 1 : 0.1));
