    W.loops.forEach((Lp) => { const v = new Vector3(); for (let k = 0; k < 8; k++) { tubeAt(Lp.path, 26 + k * 7, v); lamp('star', v.x, v.z, 1.6, 1.6, 0, L.ins[k % 2 ? 1 : 4], chase(k, 8, 0.8)); } });
