    const lg = g.createLinearGradient(0, 0, 0, 64); lg.addColorStop(0, '#9FEFFF'); lg.addColorStop(0.1, '#3AA8E8'); lg.addColorStop(0.3, '#000'); lg.addColorStop(1, '#000');
