  burst(ball.p.x, ball.p.y, ball.p.z, 0xFFB070, 24, 4); burst(ball.p.x, ball.p.y, ball.p.z, 0xFFFFFF, 10, 3);
  ball.v.set(0, 0, 0); startFall();
