      caps[0].position.set(x, top + 0.05, z); caps[1].rotation.x = Math.PI / 2; caps[1].position.set(x, top + 0.53, z);
      const glow = spDisc(x, top + 0.006, z, 0.78, glowMat(0x5FE8FF, 0.5, dot));
