  ctx.fillStyle = col; ctx.font = '800 16px Inter, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(ch, x, y + 1);
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
