    ctx.beginPath(); ctx.arc(cx + w * 0.18, my + 6, 8, 0, Math.PI * 2); ctx.fillStyle = IC.twin; ctx.fill();
    introArrow(cx + w * 0.14, my + 6, cx + w * 0.06, my + 6, IC.twin);
