      g.strokeStyle = 'rgba(40,20,8,0.25)'; g.lineWidth = 3; for (let k = 20; k < 256; k += 14) { g.beginPath(); g.arc(256, 256, k, 0, Math.PI * 2); g.stroke(); }   // raked
