  for (let k = 0; k < 9; k++) tl(g, tlEll(g, 202 + k * 13.5, 306 + Math.abs(k - 4) * 1.5, 12, 9), k % 2 ? '#F48AB0' : '#FFB8D0', { lw: 3 });   // the tutu
