  for (let k = 0; k < 16; k++) { const a = k / 16 * Math.PI * 2; for (const dz of [-1.2, 1.2]) WB.geo(new CylinderGeometry(0.1, 0.1, FR, 4), placeAt(Math.cos(a) * FR / 2, Math.sin(a) * FR / 2, dz, 0, 0, a + Math.PI / 2), 0xC8C0B0); }
