    for (let k = 0; k < n; k++) { const p = new Vector3(-(w - 0.3) / 2 + (k + 0.5) * (w - 0.3) / n, h * 0.84, c.half.z + 0.02).applyMatrix4(at); bulbs.push(p.toArray()); }
