    flat(z - 2, 4, y, FC_W); const e = FC_D / 2 + 0.05, zc = z - 4 - spec.g - e; flat(zc - spec.g - e - 2.5, 5, y, FC_W);
    pieces.push({ ...spec, x, z: cr2(zc), y, w: FC_W, d: 2 * (spec.g + e), phase: 0 });
