// ---- THE TRAPEZE ----
function trapGeom(pc) { const a = Math.asin(Math.min(0.9, (pc.gap - TRAP_D) / 2 / TRAP_L)); return { a, py: pc.y + TRAP_L * Math.cos(a) }; }
