  for (const s of [-1, 1]) arch.geo(new BoxGeometry(0.5, 3.4, 0.6), placeAt(pc.x + s * (pc.w / 2 + 0.35), pc.y + 1.7, pc.z + 0.2), 0x6A2A9A);
  arch.geo(new BoxGeometry(pc.w + 1.3, 0.5, 0.7), placeAt(pc.x, pc.y + 3.4, pc.z + 0.2), 0x6A2A9A);
