  car.geo(new BoxGeometry(1.5, 0.5, CO_LEN), placeAt(0, -0.05, 0), 0xE8303A);
  car.geo(new BoxGeometry(1.56, 0.08, CO_LEN + 0.06), placeAt(0, 0.22, 0), 0xF2C230);
