  const pool = new Mesh(new CircleGeometry(9, 40), glowMat(0xFFD89A, 0.35, dot)); pool.rotation.x = -Math.PI / 2; pool.position.set(lampAt[0] - 13, DESK + 0.03, lampAt[1]); G.add(pool);
