    const hand = (len, w2, col2) => { const h2 = new Mesh(new BoxGeometry(w2, len, 0.06), new MeshBasicMaterial({ color: col2 })); h2.geometry.translate(0, len / 2, 0); h2.position.set(0, 3.2, 0.64); ck.add(h2); return h2; };
